 item={'key':a['key'],'article':f"/notizie/{a['slug']}.html",'aiGenerated':True,'sensitiveContext':a['sensitive'],'documentaryPhoto':False,'prompt':('Neutral editorial portrait of an anonymous African public-health worker in clean PPE on an isolated clinical backdrop; no patients, symptoms, suffering, procedures, text or logos.' if a['sensitive'] else 'Ultra-realistic editorial view of a Gulf oil terminal and distant tanker suggesting physical oil supply and Hormuz; no conflict, people, logos, text or documentary claim.'),'variants':variants,'alt':a['alt'],'disclosure':CAPTION,'portraitOnly':a['sensitive'],'portraitFormat':('neutral-isolated' if a['sensitive'] else 'contextual-editorial-scene'),'reenactedEvent':False}
